sys.path.insert(0,'/tmp/kbspec')
from kb import grab

def seg(t, rows=range(8,15), lo=1, hi=78):
    out=[]
    for r in rows:
        s=''.join(c.ch for c in t.grid[r])
        inner=s[lo:hi]
        stripped=inner.rstrip()
        start=len(stripped)-len(stripped.lstrip(' ')) if stripped.strip() else None
        if start is None:
            out.append((r,None,None,''))
        else:
            body=stripped[start:]
            out.append((r, lo+start, lo+len(stripped)-1, body))
    return out

def report(args, rows=range(8,15), **kw):
    t,raw=grab(args, **kw)
    print('$ ./executable ' + ' '.join(args))
    for r,a,b,body in seg(t, rows):
        if a is None:
            print('  r%02d  (blank)' % r)
        else:
            print('  r%02d  col %2d..%2d  len=%2d  |%s|' % (r,a,b,len(body),body))
    return t,raw

if __name__=='__main__':
    import json
    args=sys.argv[1:]
    report(args)

